def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    x_best = -5 + 10 * rng.random((dim))
    f_best = func(clip(x_best, lb, ub))

    for i in range(budget):
        sigma = 0.1 / (i ** 0.3 + 1)
        noise = rng.normal(size=(dim,))
        x_new = clip(x_best + sigma * noise, lb, ub)
        f_new = func(clip(x_new, lb, ub))

        if f_new < f_best:
            x_best = x_new
            f_best = f_new

    return x_best
